<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\{HttpException,Request};
use Sentinel\Tests\FieldFixture;

final class SiteAssuranceTest extends TestCase
{
    private function fixture(): array {[$app,$db,$ctx]=FieldFixture::create();return [$app->container()->make('site_assurance_service'),$app->container()->make('evidence_retention_service'),$db,$ctx,$app];}
    private function rejects(callable $work,int $status): void {try{$work();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode());}}
    private function shift($db,int $id=1,int $employee=2,int $site=1,string $start='-30 minutes',string $end='+8 hours'): void {$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(:id,101,:employee,:site,:start,:end,'ASSIGNED')",['id'=>$id,'employee'=>$employee,'site'=>$site,'start'=>gmdate('Y-m-d H:i:s',strtotime($start)),'end'=>gmdate('Y-m-d H:i:s',strtotime($end))]);}
    private function incident($db): void {$db->execute("INSERT INTO incidents(incident_uuid,company_id,site_id,incident_number,incident_type,incident_category,occurred_at,description) VALUES('case',101,1,'INC-1','FIELD','FIELD',:now,'Investigation test')",['now'=>gmdate('Y-m-d H:i:s')]);}
    private function evidence($e): array {return $e->addEvidence(['incident_id'=>1,'original_filename'=>'original.bin','file_base64'=>base64_encode("Original\x00bytes\xff"),'description'=>'Original capture','captured_at'=>gmdate('Y-m-d H:i:s')]);}
    public function testInstructionsKeepVersionsAndRequireAcknowledgingTheCurrentAssignedRevision(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->shift($db);$input=['site_id'=>1,'expected_revision'=>0,'title'=>'Gate duty','instructions'=>'Read the current post procedure.','emergency_contacts'=>'Control room extension 10'];$first=$s->publishInstructions($input);$ctx->setUser('2');self::assertFalse($s->guardWorkspace()['instructions'][0]['acknowledged']);$s->acknowledgeInstructions($first['id']);$s->acknowledgeInstructions($first['id']);self::assertCount(1,$s->list('acknowledgements'));$ctx->setUser('1');$second=$s->publishInstructions([...$input,'expected_revision'=>1,'instructions'=>'Updated procedure.']);self::assertCount(2,$s->list('instructions'));$this->rejects(fn()=>$s->publishInstructions($input),409);$ctx->setUser('2');$this->rejects(fn()=>$s->acknowledgeInstructions($first['id']),409);self::assertFalse($s->guardWorkspace()['instructions'][0]['acknowledged']);self::assertSame($second['id'],(string)$s->guardWorkspace()['instructions'][0]['instruction_id']);$ctx->setUser('3');$ctx->setTenantId(202);self::assertSame([],$s->guardWorkspace()['instructions']);$this->rejects(fn()=>$s->acknowledgeInstructions($second['id']),404);
    }
    public function testUnassignedGuardCannotReadSiteInstructionsOrAcknowledgeThem(): void {
        [$s]=$this->fixture();$first=$s->publishInstructions(['site_id'=>1,'expected_revision'=>0,'title'=>'Procedure','instructions'=>'Restricted duty instructions','emergency_contacts'=>'Company contact']);self::assertSame([],$s->guardWorkspace()['instructions']);$this->rejects(fn()=>$s->acknowledgeInstructions($first['id']),404);
    }
    public function testHandoverRecordsChecklistAndOnlyReceivingGuardCanAcceptIt(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->shift($db,1,1,1,'-10 hours','-15 minutes');$this->shift($db,2,2);$this->incident($db);$input=['source_shift_id'=>1,'target_shift_id'=>2,'keys_summary'=>'Keys K1/K2 present','equipment_summary'=>'Radio checked','open_incident_ids'=>[1],'outstanding_tasks'=>'Follow up gate fault'];$handover=$s->createHandover($input,true);$this->rejects(fn()=>$s->acceptHandover($handover['id'],['receiver_notes'=>'Checked']),404);$ctx->setUser('2');self::assertTrue($s->guardWorkspace()['handovers'][0]['can_accept']);$s->acceptHandover($handover['id'],['receiver_notes'=>'Counted keys and tested radio.']);self::assertFalse($s->guardWorkspace()['handovers'][0]['can_accept']);$this->rejects(fn()=>$s->acceptHandover($handover['id'],['receiver_notes'=>'Repeat']),409);self::assertSame(2,(int)$s->list('handovers')[0]['accepted_by_user_id']);
    }
    public function testHandoverRejectsUnrelatedShiftsAndResolvedIncidentReferences(): void {
        [$s,$e,$db]=$this->fixture();$this->shift($db,1,1);$this->shift($db,2,2,2);$input=['source_shift_id'=>1,'target_shift_id'=>2,'keys_summary'=>'Keys','equipment_summary'=>'Radio','open_incident_ids'=>[],'outstanding_tasks'=>'None'];$this->rejects(fn()=>$s->createHandover($input),422);$db->execute('UPDATE shift_assignments SET site_id=1 WHERE shift_assignment_id=2');$this->incident($db);$db->execute("UPDATE incidents SET status='RESOLVED'");$this->rejects(fn()=>$s->createHandover([...$input,'open_incident_ids'=>[1]]),422);
    }
    public function testTrainingRequiresVerificationFullShiftValidityAndNoRevocation(): void {
        [$s,$e,$db]=$this->fixture();$this->shift($db,1,2,1,'+1 day','+2 days');$c=$s->competency(['competency_code'=>'FIRST_AID','competency_name'=>'First aid']);$requirement=$s->requireTraining(['site_id'=>1,'competency_id'=>$c['id']]);self::assertCount(1,$s->trainingGaps());$t=$s->recordTraining(['employee_id'=>2,'competency_id'=>$c['id'],'reference_number'=>'CERT-1','valid_from'=>gmdate('Y-m-d'),'valid_until'=>gmdate('Y-m-d',strtotime('+3 days'))]);self::assertCount(1,$s->trainingGaps());$s->verifyTraining($t['id']);self::assertSame([],$s->trainingGaps());$s->revokeTraining($t['id'],['reason'=>'Evidence withdrawn']);self::assertCount(1,$s->trainingGaps());$this->rejects(fn()=>$s->verifyTraining($t['id']),409);$s->removeRequirement($requirement['id']);self::assertSame([],$s->trainingGaps());
    }
    public function testExpiredTrainingDoesNotSatisfyAnOvernightDuty(): void {
        [$s,$e,$db]=$this->fixture();$this->shift($db,1,2,1,'+1 day','+2 days');$c=$s->competency(['competency_code'=>'RADIO','competency_name'=>'Radio operation']);$s->requireTraining(['site_id'=>1,'competency_id'=>$c['id']]);$t=$s->recordTraining(['employee_id'=>2,'competency_id'=>$c['id'],'reference_number'=>'CERT-2','valid_from'=>gmdate('Y-m-d'),'valid_until'=>gmdate('Y-m-d',strtotime('+1 day'))]);$s->verifyTraining($t['id']);self::assertCount(1,$s->trainingGaps());
    }
    public function testMaintenanceRequiresOrderedTransitionsCurrentRevisionAndIndependentVerification(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$ticket=$s->createTicket(['site_id'=>1,'asset_type'=>'GATE','title'=>'Gate motor fault','description'=>'Gate does not close','priority'=>'HIGH','assignee_user_id'=>1]);$id=$ticket['id'];$this->rejects(fn()=>$s->ticketAction($id,'repair',['expected_revision'=>1,'notes'=>'Done']),409);$s->ticketAction($id,'start',['expected_revision'=>1,'notes'=>'Repair started']);$this->rejects(fn()=>$s->ticketAction($id,'repair',['expected_revision'=>1,'notes'=>'Done']),409);$s->ticketAction($id,'repair',['expected_revision'=>2,'notes'=>'Motor replaced and tested']);$this->rejects(fn()=>$s->ticketAction($id,'verify',['expected_revision'=>3,'notes'=>'Checked']),403);$ctx->setUser('2');self::assertSame('VERIFIED',$s->ticketAction($id,'verify',['expected_revision'=>3,'notes'=>'Independent test passed'])['state']);self::assertCount(4,$s->ticketHistoryList($id));$ctx->setTenantId(202);$this->rejects(fn()=>$s->ticketHistoryList($id),404);
    }
    public function testServiceReportUsesDailyTargetsAndExposesOnlyMappedClientAggregates(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$day=gmdate('Y-m-d');$s->serviceTarget(['site_id'=>1,'effective_from'=>$day,'response_minutes'=>10,'patrols_per_day'=>2,'guard_minutes_per_day'=>120]);$db->execute('INSERT INTO attendance VALUES(1,101,1,1,:day,:start,:end,NULL,NULL)',['day'=>$day,'start'=>$day.' 01:00:00','end'=>$day.' 02:00:00']);$db->execute('INSERT INTO patrol_routes VALUES(1,101,1)');$db->execute("INSERT INTO patrol_sessions VALUES(1,101,1,NULL,NULL,:start,'COMPLETED',NULL)",['start'=>$day.' 01:00:00']);$params=['site_id'=>1,'date_from'=>$day,'date_to'=>$day];$r=$s->serviceReport($params);self::assertSame(60,$r['days'][0]['guard_minute_shortfall']);self::assertSame(1,$r['days'][0]['patrol_shortfall']);self::assertNull($r['days'][0]['average_response_seconds']);$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$ctx->setUser('2');self::assertSame('Own site',$s->serviceReport($params,true)['site_name']);$this->rejects(fn()=>$s->serviceReport([...$params,'site_id'=>2],true),404);self::assertStringNotContainsString('employee_id',json_encode($s->serviceReport($params,true)));
    }
    public function testMissingServiceTargetsRemainUnknownRatherThanPassing(): void {
        [$s]=$this->fixture();$r=$s->serviceReport(['site_id'=>1,'date_from'=>gmdate('Y-m-d'),'date_to'=>gmdate('Y-m-d')]);self::assertNull($r['days'][0]['target']);self::assertNull($r['days'][0]['guard_minute_shortfall']);self::assertNull($r['days'][0]['late_arrivals_against_target']);
    }
    public function testEvidencePreservesOriginalBytesLinksCorrectionsAndAuditsDownloads(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->incident($db);$first=$this->evidence($e);$download=$e->download($first['id']);self::assertSame("Original\x00bytes\xff",$download['bytes']);self::assertSame(hash('sha256',$download['bytes']),$first['sha256']);$second=$e->addEvidence(['incident_id'=>1,'original_filename'=>'correction.txt','file_base64'=>base64_encode('Correction'),'description'=>'Linked correction','captured_at'=>gmdate('Y-m-d H:i:s'),'supersedes_evidence_id'=>$first['id']]);$pack=$e->investigationPack('1');self::assertCount(2,$pack['evidence']);self::assertSame($first['id'],(string)$pack['evidence'][1]['supersedes_evidence_id']);self::assertSame("Original\x00bytes\xff",base64_decode($pack['evidence'][0]['file_base64']));self::assertCount(2,$e->history($first['id']));$ctx->setTenantId(202);$this->rejects(fn()=>$e->download($second['id']),404);$this->rejects(fn()=>$e->investigationPack('1'),404);
    }
    public function testCorruptedEvidenceIsNotDownloadedAndFailureIsRecorded(): void {
        [$s,$e,$db]=$this->fixture();$this->incident($db);$item=$this->evidence($e);$db->execute("UPDATE incident_evidence SET file_base64='Y29ycnVwdGVk'");$this->rejects(fn()=>$e->download($item['id']),409);self::assertSame('integrity_failed',$e->history($item['id'])[0]['action_name']);$this->rejects(fn()=>$e->investigationPack('1'),409);
    }
    public function testEvidenceRejectsPathFilenamesAndOversizeFiles(): void {
        [$s,$e,$db]=$this->fixture();$this->incident($db);$base=['incident_id'=>1,'original_filename'=>'../secret.txt','file_base64'=>base64_encode('test'),'description'=>'Bad path','captured_at'=>gmdate('Y-m-d H:i:s')];$this->rejects(fn()=>$e->addEvidence($base),422);$this->rejects(fn()=>$e->addEvidence([...$base,'original_filename'=>'large.bin','file_base64'=>base64_encode(str_repeat('x',262145))]),422);self::assertSame([],$e->evidenceList(['incident_id'=>1]));
    }
    public function testIncidentHoldProtectsCurrentAndFutureEvidenceAndMobilePhotos(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->incident($db);$ctx->setMfaVerified(true);$hold=$e->hold(['category'=>'incident','record_id'=>1,'reason'=>'Open investigation']);$this->evidence($e);$db->execute("UPDATE incident_evidence SET received_at='2025-01-01 00:00:00'");$db->execute("INSERT INTO report_photos(company_id,report_type,report_id,image_base64,created_by_user_id,created_at) VALUES(101,'incident',1,'test',1,'2025-01-01 00:00:00')");foreach(['incident_evidence','report_photos']as$category){$e->policy(['category'=>$category,'retention_days'=>30]);self::assertSame(0,$e->preview(['category'=>$category])['count']);}$e->releaseHold($hold['id'],['reason'=>'Investigation retention approved for release']);self::assertSame(1,$e->preview(['category'=>'incident_evidence'])['count']);self::assertSame(1,$e->preview(['category'=>'report_photos'])['count']);
    }
    public function testRetentionRequiresMfaCurrentPreviewAndExplicitConfirmation(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->rejects(fn()=>$e->policy(['category'=>'gate_records','retention_days'=>7]),403);$ctx->setMfaVerified(true);$e->policy(['category'=>'gate_records','retention_days'=>7]);$db->execute("INSERT INTO gate_register(company_id,operation_uuid,request_hash,site_id,visitor_name,purpose,direction,authorization,occurred_at,received_at,recorded_by_user_id) VALUES(101,'capture','hash',1,'Visitor','Delivery','ENTRY','PENDING','2025-01-01 00:00:00','2025-01-01 00:00:00',1)");$p=$e->preview(['category'=>'gate_records']);self::assertSame(1,$p['count']);$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'yes']),422);$hold=$e->hold(['category'=>'gate_records','record_id'=>1,'reason'=>'Investigate visit']);$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']),409);self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM gate_register')['n']);$e->releaseHold($hold['id'],['reason'=>'Review complete']);$fresh=$e->preview(['category'=>'gate_records']);self::assertSame(1,$e->executeRetention(['preview_code'=>$fresh['preview_code'],'confirmation'=>'DELETE EXPIRED DATA'])['count']);$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$fresh['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']),409);
    }
    public function testEvidenceRetentionRemovesBytesButPreservesHashAndAccessReceipts(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$this->incident($db);$item=$this->evidence($e);$db->execute("UPDATE incident_evidence SET received_at='2025-01-01 00:00:00'");$ctx->setMfaVerified(true);$e->policy(['category'=>'incident_evidence','retention_days'=>30]);$p=$e->preview(['category'=>'incident_evidence']);$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']);$row=$db->fetch('SELECT file_base64,sha256,purged_at FROM incident_evidence');self::assertSame('',$row['file_base64']);self::assertSame($item['sha256'],$row['sha256']);self::assertNotNull($row['purged_at']);$this->rejects(fn()=>$e->download($item['id']),404);self::assertSame('REMOVED_BY_RETENTION',$e->investigationPack('1')['evidence'][0]['file_status']);self::assertSame('retention_removed',$e->history($item['id'])[0]['action_name']);
    }
    public function testVisitorAnonymisationPreservesVisitReferencesAndSkipsActiveVisits(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$ctx->setMfaVerified(true);$db->execute('CREATE TABLE visitors(visitor_id INTEGER PRIMARY KEY,company_id INTEGER,first_name TEXT,last_name TEXT,contact_phone TEXT,contact_email TEXT,external_reference TEXT,visitor_status TEXT,updated_at TEXT)');$db->execute('CREATE TABLE visitor_visits(visitor_visit_id INTEGER PRIMARY KEY,company_id INTEGER,visitor_id INTEGER,visit_status TEXT)');$db->execute("INSERT INTO visitors VALUES(1,101,'A','Visitor','123','a@example.test','ref','ACTIVE','2025-01-01 00:00:00'),(2,101,'B','Visitor',NULL,NULL,NULL,'ACTIVE','2025-01-01 00:00:00'),(3,202,'Other','Company',NULL,NULL,NULL,'ACTIVE','2025-01-01 00:00:00')");$db->execute("INSERT INTO visitor_visits VALUES(1,101,1,'CHECKED_OUT'),(2,101,2,'CHECKED_IN')");$e->policy(['category'=>'visitor_profiles','retention_days'=>30]);$p=$e->preview(['category'=>'visitor_profiles']);self::assertSame([1],$p['candidate_ids']);$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']);self::assertSame('REDACTED',$db->fetch('SELECT first_name FROM visitors WHERE visitor_id=1')['first_name']);self::assertSame('B',$db->fetch('SELECT first_name FROM visitors WHERE visitor_id=2')['first_name']);self::assertSame('Other',$db->fetch('SELECT first_name FROM visitors WHERE visitor_id=3')['first_name']);self::assertSame(1,(int)$db->fetch('SELECT visitor_id FROM visitor_visits WHERE visitor_visit_id=1')['visitor_id']);
    }
    public function testPreviewIsBoundToActorAndPolicyAndExpires(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$ctx->setMfaVerified(true);$e->policy(['category'=>'report_photos','retention_days'=>30]);$p=$e->preview(['category'=>'report_photos']);$ctx->setUser('2');$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']),404);$ctx->setUser('1');$e->policy(['category'=>'report_photos','retention_days'=>60]);$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']),409);$p=$e->preview(['category'=>'report_photos']);$db->execute("UPDATE retention_previews SET expires_at='2025-01-01 00:00:00'");$this->rejects(fn()=>$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']),409);
    }
    public function testGuardAndPasswordOnlyAccountsCannotUsePrivilegedRoutes(): void {
        [$s,$e,$db,$ctx,$app]=$this->fixture();$guard=$app->jwt()->createToken('2');foreach(['/api/v1/assurance/evidence?incident_id=1','/api/v1/assurance/retention','/api/v1/assurance/training']as$path){$this->rejects(fn()=>$app->handle(Request::create('GET',explode('?',$path)[0],[],['Authorization'=>'Bearer '.$guard])),403);}$manager=$app->jwt()->createToken('1');$this->rejects(fn()=>$app->handle(Request::create('POST','/api/v1/assurance/retention/policy',[],['Authorization'=>'Bearer '.$manager,'Content-Type'=>'application/json'],'{"category":"report_photos","retention_days":30}')),403);
    }
    public function testCleanupRollsBackRecordsAndPreviewConsumptionWhenAuditFails(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$ctx->setMfaVerified(true);$e->policy(['category'=>'report_photos','retention_days'=>30]);$db->execute("INSERT INTO report_photos(company_id,report_type,report_id,image_base64,created_by_user_id,created_at) VALUES(101,'incident',1,'photo',1,'2025-01-01 00:00:00')");$p=$e->preview(['category'=>'report_photos']);$db->connection()->exec("CREATE TRIGGER reject_cleanup_audit BEFORE INSERT ON audit_logs WHEN NEW.action_name='batch_completed' BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");try{$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']);self::fail('Cleanup should fail closed.');}catch(\PDOException){self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM report_photos')['n']);self::assertNull($db->fetch('SELECT consumed_at FROM retention_previews')['consumed_at']);}
    }
    public function testLocationPoliciesAreSeparateAndHoldsProtectSelectedHistory(): void {
        [$s,$e,$db,$ctx]=$this->fixture();$ctx->setMfaVerified(true);$db->execute('ALTER TABLE gps_locations ADD COLUMN gps_location_id INTEGER');$db->execute("INSERT INTO gps_locations(company_id,employee_id,captured_at,gps_location_id) VALUES(101,1,'2025-01-01 00:00:00',1),(202,3,'2025-01-01 00:00:00',2)");$db->execute('CREATE TABLE gps_events(gps_event_id INTEGER PRIMARY KEY,company_id INTEGER,occurred_at TEXT)');$db->execute("INSERT INTO gps_events VALUES(1,101,'2025-01-01 00:00:00')");$e->policy(['category'=>'location_history','retention_days'=>30]);$e->policy(['category'=>'location_events','retention_days'=>30]);$e->hold(['category'=>'location_history','record_id'=>1,'reason'=>'Investigate location']);self::assertSame(0,$e->preview(['category'=>'location_history'])['count']);$p=$e->preview(['category'=>'location_events']);self::assertSame(1,$p['count']);$e->executeRetention(['preview_code'=>$p['preview_code'],'confirmation'=>'DELETE EXPIRED DATA']);self::assertSame(2,(int)$db->fetch('SELECT COUNT(*) AS n FROM gps_locations')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM gps_events')['n']);
    }
}
